// ----- Ajustes (se precisar mudar algo, mude só aqui) -----
const LEADS_POR_DIA     = 6; // máximo de leads enriquecidos por dia útil
const CUSTO_POR_LEAD    = 7; // créditos gastos por lead (estimativa: 6 do contato + 1 da empresa)
const TAXA_DAS_CHAMADAS = 2; // créditos fixos por dia (1 chamada de contatos + 1 de empresas)
// -----------------------------------------------------------

// Saldo de créditos que a Lusha acabou de informar.
const saldo = Number($json.credits?.remaining);

// Se a Lusha não devolveu o saldo, é melhor parar com erro do que gastar sem saber.
if (!Number.isFinite(saldo)) {
  throw new Error("Não consegui ler o saldo de créditos da Lusha.");
}

// Quantos leads o saldo de hoje consegue pagar (já descontando a taxa das chamadas).
const leadsQueOSaldoPaga = Math.floor((saldo - TAXA_DAS_CHAMADAS) / CUSTO_POR_LEAD);

// Limite de hoje: o menor entre o máximo por dia e o que o saldo paga.
const limite = Math.max(0, Math.min(LEADS_POR_DIA, leadsQueOSaldoPaga));

// Sem saldo para nem 1 lead: não devolve nada, o fluxo para aqui e não dá erro.
if (limite < 1) {
  return [];
}

return [{ json: { saldo, limite } }];

// Junta os IDs dos leads de hoje em duas listas (contatos e empresas),
// sem repetir e sem vazios, para mandar tudo de uma vez para a Lusha.
const leads = items.map((i) => i.json);
const unico = (lista) => [...new Set(lista.filter(Boolean))];

const contactIds = unico(leads.map((l) => l.lusha_contact_id));
const companyIds = unico(leads.map((l) => l.id_company_lusha));

// Sem nenhum contato para enriquecer, não faz nada.
if (!contactIds.length) return [];

return [{ json: { contactIds, companyIds } }];

